const CLINICS_KEY = 'careledger-clinics-v1';
const PATIENTS_KEY = 'careledger-patients-v1';
const seedClinics = [{ id: 'clinic-shanti', name: 'Shanti Dental', address: 'Kathmandu', phone: '', doctorSharePercent: 70 }];
const seedPatients = [
  { id: 'p1', clinicId: 'clinic-shanti', name: 'Maya Patel', treatment: 'Root canal treatment', total: 1850, notes: 'Two-part payment plan', createdAt: '2026-09-03', payments: [{ id: 'pay1', amount: 900, date: '2026-09-10', note: 'Card payment' }], visits: [{ id: 'v1', date: '2026-09-10', type: 'Monthly visit', note: 'Treatment started' }] },
  { id: 'p2', clinicId: 'clinic-shanti', name: 'Daniel Kim', treatment: 'Ceramic crown', total: 2400, notes: '', createdAt: '2026-08-24', payments: [{ id: 'pay2', amount: 800, date: '2026-09-04', note: 'Transfer' }, { id: 'pay3', amount: 600, date: '2026-09-18', note: 'Card payment' }], visits: [{ id: 'v2', date: '2026-09-18', type: 'Monthly visit', note: 'Crown fitting' }] },
  { id: 'p3', clinicId: 'clinic-shanti', name: 'Sofia Garcia', treatment: 'Teeth whitening', total: 680, notes: '', createdAt: '2026-09-11', payments: [{ id: 'pay4', amount: 680, date: '2026-09-12', note: 'Paid in full' }], visits: [{ id: 'v3', date: '2026-09-12', type: 'Monthly visit', note: 'Completed' }] },
  { id: 'p4', clinicId: 'clinic-shanti', name: 'Noah Williams', treatment: 'Dental implant', total: 3200, notes: 'Monthly installments', createdAt: '2026-09-01', payments: [{ id: 'pay5', amount: 1200, date: '2026-09-06', note: 'Card payment' }], visits: [{ id: 'v4', date: '2026-09-06', type: 'Monthly visit', note: 'Implant review' }] }
];
let clinics = loadClinics();
let patients = loadPatients();
let selectedClinicId = localStorage.getItem('careledger-selected-clinic') || clinics[0].id;
let selectedPaymentDate = localStorage.getItem('careledger-selected-payment-date') || '';
let activeFilter = 'all';
let lastPayments = [];
let toastTimer;
let editPaymentId = '';
let editPatientId = '';
let editDoctorPaymentId = '';
const BsDate = NepaliDate.default || NepaliDate;

function loadClinics() { const stored = localStorage.getItem(CLINICS_KEY); return (stored ? JSON.parse(stored) : seedClinics).map(clinic => ({ ...clinic, doctorSharePercent: Number(clinic.doctorSharePercent ?? 70), doctorPayments: clinic.doctorPayments || [] })); }
function saveClinics() { localStorage.setItem(CLINICS_KEY, JSON.stringify(clinics)); }
function loadPatients() { const stored = localStorage.getItem(PATIENTS_KEY); const records = stored ? JSON.parse(stored) : seedPatients; return records.map(patient => ({ ...patient, clinicId: patient.clinicId || clinics[0].id, payments: patient.payments || [], visits: patient.visits || [] })); }
function savePatients() { localStorage.setItem(PATIENTS_KEY, JSON.stringify(patients)); }
function activeClinic() { return clinics.find(clinic => clinic.id === selectedClinicId) || clinics[0]; }
function clinicPatients() { return patients.filter(patient => patient.clinicId === selectedClinicId); }
function clinicName(id) { return clinics.find(clinic => clinic.id === id)?.name || 'Unknown clinic'; }
function money(value) { return `NPR ${new Intl.NumberFormat('en-IN', { maximumFractionDigits: 0 }).format(value || 0)}`; }
function moneyExact(value) { return `NPR ${new Intl.NumberFormat('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(value || 0)}`; }
function paidFor(patient) { return patient.payments.reduce((sum, payment) => sum + Number(payment.amount), 0); }
function balanceFor(patient) { return Math.max(0, patient.total - paidFor(patient)); }
function isCleared(patient) { return balanceFor(patient) === 0; }
const SETUP_KEY = 'careledger-setup-v1';
const STATUS_TONES = ['blue', 'red', 'green', 'amber', 'purple', 'slate'];
const defaultSetup = { plans: [{ id: 'plan-rct', name: 'Root canal treatment', cost: 1850, notes: '' }, { id: 'plan-crown', name: 'Ceramic crown', cost: 2400, notes: '' }, { id: 'plan-whitening', name: 'Teeth whitening', cost: 680, notes: '' }, { id: 'plan-implant', name: 'Dental implant', cost: 3200, notes: 'Monthly installments' }], statuses: [{ id: 'ongoing', label: 'Ongoing', tone: 'blue' }, { id: 'outstanding', label: 'Outstanding', tone: 'red' }, { id: 'cleared', label: 'Cleared', tone: 'green' }] };
function loadSetup() { try { const stored = JSON.parse(localStorage.getItem(SETUP_KEY)); if (stored?.statuses?.length) return { plans: stored.plans || [], statuses: stored.statuses }; } catch {} return structuredClone(defaultSetup); }
function saveSetup() { localStorage.setItem(SETUP_KEY, JSON.stringify(setup)); }
let setup = loadSetup();
function statusById(id) { return setup.statuses.find(status => status.id === id); }
function patientStatus(patient) { if (statusById(patient.status)) return patient.status; const fallback = statusById(isCleared(patient) ? 'cleared' : 'outstanding'); return (fallback || setup.statuses[0]).id; }
function statusBadge(patient) { const status = statusById(patientStatus(patient)); return `<span class="status-badge tone-${status.tone}">${status.label}</span>`; }
function statusSelect(patient) { const current = statusById(patientStatus(patient)); return `<select class="status-select tone-${current.tone}" data-status-patient="${patient.id}" aria-label="Status for ${patient.name}">${setup.statuses.map(status => `<option value="${status.id}"${status.id === current.id ? ' selected' : ''}>${status.label}</option>`).join('')}</select>`; }
function initials(name) { return name.split(' ').map(part => part[0]).slice(0, 2).join('').toUpperCase(); }
function avatarClass(index) { return ['','alt','blue','coral'][index % 4]; }
function bsLabel(value) { try { return new BsDate(value?.startsWith('208') ? value : new Date(`${value}T12:00:00`)).format('DD MMMM YYYY'); } catch { return value; } }
function adToBs(value) { try { return new BsDate(new Date(`${value}T12:00:00`)).format('YYYY-MM-DD'); } catch { return ''; } }
function bsToAd(value) { try { return new BsDate(value).toJsDate().toISOString().slice(0, 10); } catch { return ''; } }
function todayBs() { return new BsDate().format('YYYY-MM-DD'); }
function patientById(id) { return patients.find(patient => patient.id === id); }

function render() {
  const records = clinicPatients();
  const totalReceivables = records.reduce((sum, patient) => sum + balanceFor(patient), 0);
  const allPayments = records.flatMap(patient => patient.payments.map(payment => ({ ...payment, patient })));
  const cleared = records.filter(isCleared);
  const availableDates = [...new Set(allPayments.map(payment => payment.date))].sort((a, b) => b.localeCompare(a));
  if (!availableDates.includes(selectedPaymentDate)) selectedPaymentDate = availableDates[0] || '';
  const selectedEntries = allPayments.filter(payment => payment.date === selectedPaymentDate);
  const selectedPatients = new Set(selectedEntries.map(payment => payment.patient.id));
  const dailyCollected = selectedEntries.reduce((sum, payment) => sum + Number(payment.amount), 0);
  const doctorPayments = activeClinic().doctorPayments || [];
  const dailyDoctorReceived = doctorPayments.filter(payment => (payment.visitDate || payment.date) === selectedPaymentDate).reduce((sum, payment) => sum + Number(payment.amount), 0);
  const expectedDoctorShare = dailyCollected * (activeClinic().doctorSharePercent / 100);
  document.querySelector('#paymentCountLabel').textContent = `${selectedEntries.length} payment${selectedEntries.length === 1 ? '' : 's'}`;
  document.querySelector('#dailyPatientCount').textContent = selectedPatients.size;
  document.querySelector('#dailyEntryLabel').textContent = `${selectedEntries.length} entr${selectedEntries.length === 1 ? 'y' : 'ies'}`;
  document.querySelector('#dailyCollected').textContent = money(dailyCollected);
  const dailyDoctorDue = Math.max(0, expectedDoctorShare - dailyDoctorReceived);
  document.querySelector('#dailyDoctorShare').textContent = money(dailyDoctorDue);
  document.querySelector('#dailyDoctorShare').classList.toggle('due-amount', dailyDoctorDue > 0);
  const doctorShareTotal = allPayments.reduce((sum, payment) => sum + Number(payment.amount), 0) * (activeClinic().doctorSharePercent / 100);
  const doctorReceivedTotal = doctorPayments.reduce((sum, payment) => sum + Number(payment.amount), 0);
  const doctorDueTotal = Math.max(0, doctorShareTotal - doctorReceivedTotal);
  document.querySelector('#doctorShareTotal').textContent = money(doctorShareTotal);
  document.querySelector('#doctorReceivedTotal').textContent = money(doctorReceivedTotal);
  document.querySelector('#doctorDueTotal').textContent = money(doctorDueTotal);
  document.querySelector('#doctorDueTotal').classList.toggle('due-amount', doctorDueTotal > 0);
  document.querySelector('#doctorPaymentCountLabel').textContent = `${doctorPayments.length} payment${doctorPayments.length === 1 ? '' : 's'}`;
  document.querySelector('#overviewDoctorClinic').textContent = activeClinic().name;
  document.querySelector('#overviewDoctorPercent').textContent = activeClinic().doctorSharePercent;
  document.querySelector('#mobileClinicName').textContent = activeClinic().name;
  const doctorSharePercentLabel = document.querySelector('#doctorSharePercentLabel');
  const doctorSettlementLine = document.querySelector('#doctorSettlementLine');
  const dailyDoctorReceivedLabel = document.querySelector('#dailyDoctorReceived');
  if (doctorSharePercentLabel) doctorSharePercentLabel.textContent = activeClinic().doctorSharePercent;
  if (doctorSettlementLine) doctorSettlementLine.textContent = `Expected ${money(expectedDoctorShare)} - Received ${money(dailyDoctorReceived)}`;
  if (dailyDoctorReceivedLabel) dailyDoctorReceivedLabel.textContent = money(dailyDoctorReceived);
  document.querySelector('#patientCount').textContent = records.length;
  renderStatusTabs(records);
  document.querySelector('#pageTitle').textContent = activeClinic().name;
  document.querySelector('#paymentClinicLabel').textContent = activeClinic().name;
  document.querySelector('#doctorPaymentClinicLabel').textContent = activeClinic().name;
  document.querySelector('#paymentDateSelect').innerHTML = availableDates.length ? availableDates.map(date => `<option value="${date}">${bsLabel(date)}</option>`).join('') : '<option value="">No payment dates</option>';
  document.querySelector('#paymentDateSelect').value = selectedPaymentDate;
  renderOverviewTable(selectedEntries); renderPatientsTable(); renderActivity(selectedEntries); renderReports(totalReceivables, cleared); renderPayments(allPayments); renderDoctorPayments(); populateClinicControls(); populatePaymentSelect(); renderSetup();
}

function patientRow(patient, index, compact = false) {
  const paid = paidFor(patient); const balance = balanceFor(patient); const percent = patient.total ? Math.min(100, Math.round((paid / patient.total) * 100)) : 0; const pendingPercent = patient.total ? Math.round((balance / patient.total) * 100) : 0;
  const entryDates = [...new Set([...patient.payments, ...patient.visits].map(entry => bsLabel(entry.bsDate || entry.date)))].sort();
  if (compact) return `<tr><td><div class="patient-name" title="${patient.phone || ''}${patient.address ? ` · ${patient.address}` : ''}"><span class="patient-avatar ${avatarClass(index)}">${initials(patient.name)}</span>${patient.name}</div></td><td class="treatment">${patient.treatment}</td><td class="progress-cell"><div class="progress-row"><span>${money(paid)} paid</span><span>${percent}%</span></div><div class="progress-bar"><i style="width:${percent}%"></i></div></td><td class="balance">${money(balance)}</td><td>${statusBadge(patient)}</td><td><button class="row-action" data-pay="${patient.id}" title="Record payment">＋</button></td></tr>`;
  return `<tr><td><button class="patient-name patient-link" data-history-patient="${patient.id}" title="Open patient payment history"><span class="patient-avatar ${avatarClass(index)}">${initials(patient.name)}</span>${patient.name}</button></td><td class="treatment">${patient.treatment}</td><td>${money(patient.total)}</td><td>${money(paid)}</td><td class="balance">${money(balance)}</td><td class="pending-percent">${pendingPercent}%</td><td class="entry-dates">${entryDates.length ? entryDates.map(date => `<span>${date}</span>`).join('') : '<span class="muted-entry">No entries</span>'}</td><td>${statusSelect(patient)}</td><td><button class="row-action" data-edit-patient="${patient.id}" title="Edit patient">✎</button><button class="row-action" data-visit="${patient.id}" title="Log patient visit">＋</button><button class="row-action" data-pay="${patient.id}" title="Record patient visit">NPR</button></td></tr>`;
}
function renderOverviewTable(entries) { let cumulative = 0; const rows = [...entries].sort((a, b) => a.date.localeCompare(b.date)).map(payment => { cumulative += Number(payment.amount); const pendingPercent = payment.patient.total ? Math.round((balanceFor(payment.patient) / payment.patient.total) * 100) : 0; return `<tr><td><strong>${bsLabel(payment.bsDate || payment.date)}</strong></td><td><button class="patient-name patient-link" data-history-patient="${payment.patient.id}" title="Open patient payment history"><span class="patient-avatar">${initials(payment.patient.name)}</span>${payment.patient.name}</button></td><td class="treatment">${payment.patient.treatment}</td><td class="activity-amount">+${money(payment.amount)}</td><td class="pending-percent">${pendingPercent}%</td><td class="cumulative-amount">${money(cumulative)}</td><td><button class="row-action" data-edit-payment="${payment.patient.id}:${payment.id}" title="Edit entry">✎</button></td></tr>`; }).join(''); document.querySelector('#overviewTable').innerHTML = rows; document.querySelector('#overviewEmpty').classList.toggle('hidden', entries.length > 0); }
function renderPatientsTable() { const query = document.querySelector('#patientSearch').value.toLowerCase(); const visible = clinicPatients().filter(patient => (activeFilter === 'all' || patientStatus(patient) === activeFilter) && `${patient.name} ${patient.treatment}`.toLowerCase().includes(query)); document.querySelector('#patientsTable').innerHTML = visible.map((patient, index) => patientRow(patient, index)).join(''); document.querySelector('#patientsEmpty').classList.toggle('hidden', visible.length > 0); }
function renderActivity(payments) { const activity = [...payments].sort((a, b) => b.date.localeCompare(a.date)); document.querySelector('#activityList').innerHTML = activity.length ? activity.map(payment => `<div class="activity-item"><div class="activity-icon">✓</div><div class="activity-copy"><strong>${payment.patient.name}</strong><span>${payment.note || 'Patient visit'} · ${bsLabel(payment.date)}</span></div><span class="activity-amount">+${money(payment.amount)}</span></div>`).join('') : '<div class="empty-state">No patient visits on this date.</div>'; }
function searchMatches(query, ...fields) { return !query || fields.join(' ').toLowerCase().includes(query); }
function renderPayments(payments = lastPayments) { lastPayments = payments; const query = document.querySelector('#paymentSearch').value.trim().toLowerCase(); let cumulative = 0; const entries = [...payments].sort((a, b) => a.date.localeCompare(b.date)).map(payment => ({ ...payment, cumulative: cumulative += Number(payment.amount) })).filter(payment => searchMatches(query, payment.patient.name, payment.patient.treatment, payment.note || 'Patient visit completed', bsLabel(payment.bsDate || payment.date), payment.date, payment.amount)); document.querySelector('#paymentsTable').innerHTML = entries.map(payment => { const visit = bsLabel(payment.bsDate || payment.date); return `<tr><td><strong>${visit}</strong><small class="visit-month">AD ${payment.date}</small></td><td><div class="patient-name"><span class="patient-avatar">${initials(payment.patient.name)}</span>${payment.patient.name}</div></td><td class="treatment">Patient visit</td><td class="activity-amount">+${money(payment.amount)}</td><td class="cumulative-amount">${money(payment.cumulative)}</td><td class="treatment">${payment.note || 'Patient visit completed'}</td><td><button class="row-action" data-edit-payment="${payment.patient.id}:${payment.id}" title="Edit patient visit">✎</button></td></tr>`; }).join(''); document.querySelector('#paymentsEmpty').textContent = query ? 'No patient visits match your search.' : 'No patient visits recorded for this clinic yet.'; document.querySelector('#paymentsEmpty').classList.toggle('hidden', entries.length > 0); }
function doctorPaymentRow(payment) { return `<tr><td><strong>${bsLabel(payment.visitBsDate || payment.visitDate || payment.date)}</strong></td><td><strong>${bsLabel(payment.recordedBsDate || payment.recordedDate || payment.date)}</strong><small class="visit-month">AD ${payment.recordedDate || payment.date}</small></td><td class="activity-amount">${money(payment.amount)}</td><td class="treatment">${payment.note || 'Doctor payment received'}</td><td><button class="row-action" data-edit-doctor-payment="${payment.id}" title="Edit doctor payment">✎</button></td></tr>`; }
function renderDoctorPayments() { const query = document.querySelector('#doctorPaymentSearch').value.trim().toLowerCase(); const payments = [...(activeClinic().doctorPayments || [])].sort((a, b) => (b.recordedDate || b.date).localeCompare(a.recordedDate || a.date)).filter(payment => searchMatches(query, payment.note || 'Doctor payment received', bsLabel(payment.visitBsDate || payment.visitDate || payment.date), bsLabel(payment.recordedBsDate || payment.recordedDate || payment.date), payment.visitDate, payment.recordedDate || payment.date, payment.amount)); document.querySelector('#doctorPaymentsTable').innerHTML = payments.map(doctorPaymentRow).join(''); const recent = [...(activeClinic().doctorPayments || [])].sort((a, b) => (b.recordedDate || b.date).localeCompare(a.recordedDate || a.date)).slice(0, 6); document.querySelector('#overviewDoctorTable').innerHTML = recent.map(doctorPaymentRow).join(''); document.querySelector('#overviewDoctorEmpty').classList.toggle('hidden', recent.length > 0); document.querySelector('#doctorPaymentsEmpty').textContent = query ? 'No doctor payments match your search.' : 'No doctor payments recorded for this clinic yet.'; document.querySelector('#doctorPaymentsEmpty').classList.toggle('hidden', payments.length > 0); }
function renderReports(totalReceivables, cleared) { const active = clinicPatients().filter(patient => !isCleared(patient)); document.querySelector('#reportOutstandingTotal').textContent = money(totalReceivables); document.querySelector('#outstandingReport').innerHTML = active.length ? active.map(patient => `<div class="report-line"><div><strong>${patient.name}</strong><small>${patient.treatment}</small></div><strong>${money(balanceFor(patient))}</strong></div>`).join('') : '<div class="empty-state">All patient plans are cleared.</div>'; document.querySelector('#reportClearedTotal').textContent = `${cleared.length} patient${cleared.length === 1 ? '' : 's'}`; document.querySelector('#clearedReport').innerHTML = cleared.length ? cleared.map(patient => `<div class="report-line"><div><strong>${patient.name}</strong><small>${patient.treatment} · completed ${bsLabel(patient.payments.at(-1).bsDate || patient.payments.at(-1).date)}</small></div><strong>${money(patient.total)}</strong></div>`).join('') : '<div class="empty-state">No cleared plans yet.</div>'; }
function populateClinicControls() { const options = clinics.map(clinic => `<option value="${clinic.id}">${clinic.name}</option>`).join(''); document.querySelector('#clinicSwitcher').innerHTML = options; document.querySelector('#clinicSwitcher').value = selectedClinicId; document.querySelector('#patientClinicSelect').innerHTML = options; document.querySelector('#patientClinicSelect').value = selectedClinicId; }
function populatePaymentSelect(includeCleared = false) { const select = document.querySelector('#paymentPatientSelect'); select.innerHTML = '<option value="">Choose a patient</option>' + clinicPatients().filter(patient => includeCleared || !isCleared(patient)).map(patient => `<option value="${patient.id}">${patient.name} · ${money(balanceFor(patient))} due</option>`).join(''); updatePaymentPreview(); }
function populateVisitSelect(patientId = '') { const select = document.querySelector('#visitPatientSelect'); select.innerHTML = '<option value="">Choose a patient</option>' + clinicPatients().map(patient => `<option value="${patient.id}">${patient.name} · ${patient.visits.length} visits</option>`).join(''); select.value = patientId; }
function updatePaymentPreview() { const patient = patientById(document.querySelector('#paymentPatientSelect').value); document.querySelector('#paymentBalancePreview').innerHTML = patient ? `Current balance: <strong>${moneyExact(balanceFor(patient))}</strong>` : 'Select a patient to see the current balance.'; }
function openPatientHistory(patientId) { const patient = patientById(patientId); if (!patient) return; document.querySelector('#historyPatientName').textContent = patient.name; document.querySelector('#historyPatientSummary').innerHTML = `${patient.treatment} · Total ${money(patient.total)} · Paid ${money(paidFor(patient))} · Pending ${Math.round((balanceFor(patient) / patient.total) * 100)}%`; document.querySelector('#patientHistoryList').innerHTML = patient.payments.length ? [...patient.payments].sort((a, b) => a.date.localeCompare(b.date)).map(payment => `<div class="history-line"><div><strong>${bsLabel(payment.bsDate || payment.date)}</strong><small>${payment.note || 'Payment received'} · AD ${payment.date}</small></div><strong>${money(payment.amount)}</strong></div>`).join('') : '<div class="empty-state">No payments recorded for this patient.</div>'; openModal('patientHistoryModal'); }
function openDoctorPaymentModal() { openModal('doctorPaymentModal'); populateDoctorVisitSelect(selectedPaymentDate, editDoctorPaymentId); updateDoctorVisitPreview(!editDoctorPaymentId); setCalendarDate(document.querySelector('#doctorPaymentForm [name="recordedDate"]'), document.querySelector('#doctorRecordedBsPreview')); }
function openEditDoctorPayment(paymentId) { const payment = (activeClinic().doctorPayments || []).find(entry => entry.id === paymentId); if (!payment) return; editDoctorPaymentId = paymentId; openDoctorPaymentModal(); populateDoctorVisitSelect(payment.visitDate || payment.date, paymentId); updateDoctorVisitPreview(false); document.querySelector('#doctorPaymentForm [name="recordedDate"]').value = payment.recordedDate || payment.date; document.querySelector('#doctorRecordedBsPreview').textContent = `Nepali BS ${adToBs(payment.recordedDate || payment.date)}`; document.querySelector('#doctorPaymentForm [name="amount"]').value = payment.amount; document.querySelector('#doctorPaymentForm [name="note"]').value = payment.note || ''; document.querySelector('#doctorPaymentModalEyebrow').textContent = 'Correct doctor payment'; document.querySelector('#doctorPaymentModalTitle').textContent = 'Edit doctor payment'; document.querySelector('#doctorPaymentSubmitButton').textContent = 'Update doctor payment'; }
function openEditPayment(patientId, paymentId) { const patient = patientById(patientId); const payment = patient?.payments.find(entry => entry.id === paymentId); if (!payment) return; editPaymentId = paymentId; openModal('paymentModal', patientId); populatePaymentSelect(true); document.querySelector('#paymentPatientSelect').value = patientId; document.querySelector('#paymentForm [name="amount"]').value = payment.amount; document.querySelector('#paymentForm [name="adDate"]').value = payment.date; document.querySelector('#paymentBsPreview').textContent = `Nepali BS ${adToBs(payment.date)}`; document.querySelector('#paymentForm [name="note"]').value = payment.note || ''; document.querySelector('#paymentModalEyebrow').textContent = 'Correct patient visit'; document.querySelector('#paymentModalTitle').textContent = 'Edit patient visit'; document.querySelector('#paymentSubmitButton').textContent = 'Update patient visit'; updatePaymentPreview(); }
function openEditPatient(patientId) { const patient = patientById(patientId); if (!patient) return; editPatientId = patientId; openModal('patientModal'); document.querySelector('#patientClinicSelect').value = patient.clinicId; document.querySelector('#patientForm [name="name"]').value = patient.name; document.querySelector('#patientForm [name="phone"]').value = patient.phone || ''; document.querySelector('#patientForm [name="address"]').value = patient.address || ''; document.querySelector('#patientForm [name="treatment"]').value = patient.treatment; populatePatientFormChoices(patientStatus(patient), patient.planId || ''); document.querySelector('#patientForm [name="total"]').value = patient.total; document.querySelector('#patientForm [name="firstPayment"]').value = ''; document.querySelector('#patientForm [name="notes"]').value = patient.notes || ''; document.querySelector('#patientModalEyebrow').textContent = 'Patient record'; document.querySelector('#patientModalTitle').textContent = 'Edit patient'; document.querySelector('#patientSubmitButton').textContent = 'Update patient'; }
function setCalendarDate(input, preview, preferredDate = '') { const date = preferredDate || new Date().toISOString().slice(0, 10); input.value = date; preview.textContent = `Nepali BS ${adToBs(date)}`; }
function openModal(id, patientId = '') { document.querySelector(`#${id}`).classList.remove('hidden'); if (id === 'patientModal') populateClinicControls(); if (id === 'clinicModal') return; if (id === 'paymentModal') { populatePaymentSelect(); document.querySelector('#paymentPatientSelect').value = patientId; updatePaymentPreview(); setCalendarDate(document.querySelector('#paymentForm [name="adDate"]'), document.querySelector('#paymentBsPreview')); } if (id === 'visitModal') { populateVisitSelect(patientId); setCalendarDate(document.querySelector('#visitForm [name="adDate"]'), document.querySelector('#visitBsPreview')); } }
function closeModal(id) { document.querySelector(`#${id}`).classList.add('hidden'); }
function showToast(message) { const toast = document.querySelector('#toast'); toast.textContent = message; toast.classList.remove('hidden'); clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.add('hidden'), 2800); }
function showView(view) { document.querySelectorAll('.view').forEach(element => element.classList.remove('active-view')); document.querySelector(`#${view}View`).classList.add('active-view'); document.querySelectorAll('.nav-item[data-view], .tab-item[data-view]').forEach(button => button.classList.toggle('active', button.dataset.view === view)); document.body.dataset.view = view; closeDrawer(); window.scrollTo({ top: 0 }); document.querySelector('#pageTitle').textContent = activeClinic().name; if (view === 'patients') renderPatientsTable(); }

document.addEventListener('click', event => { const viewButton = event.target.closest('[data-view]'); if (viewButton) showView(viewButton.dataset.view); const closeButton = event.target.closest('[data-close]'); if (closeButton) { closeModal(closeButton.dataset.close); if (closeButton.dataset.close === 'paymentModal') editPaymentId = ''; if (closeButton.dataset.close === 'patientModal') editPatientId = ''; if (closeButton.dataset.close === 'doctorPaymentModal') editDoctorPaymentId = ''; } const payButton = event.target.closest('[data-pay]'); if (payButton) openModal('paymentModal', payButton.dataset.pay); const editButton = event.target.closest('[data-edit-payment]'); if (editButton) { const [patientId, paymentId] = editButton.dataset.editPayment.split(':'); openEditPayment(patientId, paymentId); } const doctorEditButton = event.target.closest('[data-edit-doctor-payment]'); if (doctorEditButton) openEditDoctorPayment(doctorEditButton.dataset.editDoctorPayment); const patientEditButton = event.target.closest('[data-edit-patient]'); if (patientEditButton) openEditPatient(patientEditButton.dataset.editPatient); const historyButton = event.target.closest('[data-history-patient]'); if (historyButton) openPatientHistory(historyButton.dataset.historyPatient); const visitButton = event.target.closest('[data-visit]'); if (visitButton) openModal('visitModal', visitButton.dataset.visit); const clickedId = event.target.closest('button')?.id || event.target.id; if (['recordDoctorPayment', 'addDoctorPaymentButton', 'navDoctorPayment', 'overviewRecordDoctorPayment'].includes(clickedId)) { editDoctorPaymentId = ''; document.querySelector('#doctorPaymentModalEyebrow').textContent = 'Doctor settlement'; document.querySelector('#doctorPaymentModalTitle').textContent = 'Record amount received'; document.querySelector('#doctorPaymentSubmitButton').textContent = 'Save received amount'; openDoctorPaymentModal(); } if (['addPatientButton', 'emptyAddPatient'].includes(clickedId)) { editPatientId = ''; populatePatientFormChoices(); document.querySelector('#patientModalEyebrow').textContent = 'New patient'; document.querySelector('#patientModalTitle').textContent = 'Add patient'; document.querySelector('#patientSubmitButton').textContent = 'Create patient'; openModal('patientModal'); } if (clickedId === 'addPaymentButton' || clickedId === 'openPaymentNav') { editPaymentId = ''; document.querySelector('#paymentModalEyebrow').textContent = 'Patient visit'; document.querySelector('#paymentModalTitle').textContent = 'Record patient visit'; document.querySelector('#paymentSubmitButton').textContent = 'Save patient visit'; openModal('paymentModal'); } if (clickedId === 'openClinicNav') openModal('clinicModal'); if (clickedId === 'refreshButton') { render(); showToast('Activity refreshed'); } if (clickedId === 'printReport') window.print(); const filter = event.target.closest('[data-filter]'); if (filter) { activeFilter = filter.dataset.filter; document.querySelectorAll('.filter-tab').forEach(button => button.classList.toggle('active', button === filter)); renderPatientsTable(); } });
