document.querySelector('#clinicForm').addEventListener('submit', event => { event.preventDefault(); const data = new FormData(event.target); const clinic = { id: `clinic${Date.now()}`, name: data.get('name').trim(), address: data.get('address').trim(), phone: data.get('phone').trim(), doctorSharePercent: Number(data.get('doctorSharePercent') || 70), doctorPayments: [] }; clinics.push(clinic); saveClinics(); selectedClinicId = clinic.id; localStorage.setItem('careledger-selected-clinic', selectedClinicId); render(); closeModal('clinicModal'); event.target.reset(); showToast(`${clinic.name} added with ${clinic.doctorSharePercent}% doctor share`); });
document.querySelector('#patientForm').addEventListener('submit', event => { event.preventDefault(); const data = new FormData(event.target); const total = Number(data.get('total')); const firstPayment = Number(data.get('firstPayment') || 0); if (firstPayment > total) return showToast('First payment cannot exceed the total cost.'); const existing = editPatientId ? patientById(editPatientId) : null; if (existing) { Object.assign(existing, { clinicId: data.get('clinicId'), name: data.get('name').trim(), phone: data.get('phone').trim(), address: data.get('address').trim(), treatment: data.get('treatment').trim(), status: data.get('status'), planId: data.get('planId'), total, notes: data.get('notes').trim() }); } else { const paymentDate = new Date().toISOString().slice(0, 10); const patient = { id: `p${Date.now()}`, clinicId: data.get('clinicId'), name: data.get('name').trim(), phone: data.get('phone').trim(), address: data.get('address').trim(), treatment: data.get('treatment').trim(), status: data.get('status') || setup.statuses[0].id, planId: data.get('planId'), total, notes: data.get('notes').trim(), createdAt: paymentDate, payments: firstPayment ? [{ id: `pay${Date.now()}`, amount: firstPayment, date: paymentDate, bsDate: todayBs(), note: 'Initial payment' }] : [], visits: [] }; patients.unshift(patient); } savePatients(); render(); closeModal('patientModal'); event.target.reset(); const action = existing ? 'updated' : 'added'; editPatientId = ''; showToast(`${existing?.name || data.get('name')} ${action} in ${clinicName(data.get('clinicId'))}`); });
document.querySelector('#paymentForm').addEventListener('submit', event => { event.preventDefault(); const data = new FormData(event.target); const patient = patientById(data.get('patientId')); const amount = Number(data.get('amount')); const date = data.get('adDate'); const bsDate = adToBs(date); if (!patient) return showToast('Choose a patient first.'); if (!date || !bsDate) return showToast('Choose a valid calendar date.'); const existing = editPaymentId ? patient.payments.find(payment => payment.id === editPaymentId) : null; const otherPaid = paidFor(patient) - (existing ? Number(existing.amount) : 0); if (amount + otherPaid > patient.total) return showToast('Payment cannot exceed the outstanding balance.'); if (existing) Object.assign(existing, { amount, date, bsDate, note: data.get('note').trim() }); else patient.payments.push({ id: `pay${Date.now()}`, amount, date, bsDate, note: data.get('note').trim() }); savePatients(); render(); closeModal('paymentModal'); event.target.reset(); const action = existing ? 'updated' : 'recorded'; editPaymentId = ''; showToast(`Payment ${action} for ${patient.name}`); });
document.querySelector('#visitForm').addEventListener('submit', event => { event.preventDefault(); const data = new FormData(event.target); const patient = patientById(data.get('patientId')); const date = data.get('adDate'); const bsDate = adToBs(date); if (!patient) return showToast('Choose a patient first.'); if (!date || !bsDate) return showToast('Choose a valid calendar date.'); patient.visits.push({ id: `visit${Date.now()}`, date, bsDate, type: data.get('type').trim(), note: data.get('note').trim() }); savePatients(); render(); closeModal('visitModal'); event.target.reset(); showToast(`Visit logged for ${patient.name}`); });
