document.querySelector('#doctorPaymentForm [name="recordedDate"]').addEventListener('change', event => { document.querySelector('#doctorRecordedBsPreview').textContent = `Nepali BS ${adToBs(event.target.value)}`; });
document.querySelector('#doctorPaymentForm').addEventListener('submit', event => { event.preventDefault(); const data = new FormData(event.target); const visitDate = data.get('visitDate'); const recordedDate = data.get('recordedDate'); const visitBsDate = adToBs(visitDate); const recordedBsDate = adToBs(recordedDate); const amount = Number(data.get('amount')); if (!visitDate || !recordedDate || !visitBsDate || !recordedBsDate || !amount) return showToast('Choose both dates and enter the received amount.'); const clinic = activeClinic(); clinic.doctorPayments = clinic.doctorPayments || []; const existing = editDoctorPaymentId ? clinic.doctorPayments.find(payment => payment.id === editDoctorPaymentId) : null; const values = { visitDate, visitBsDate, recordedDate, recordedBsDate, amount, note: data.get('note').trim() }; if (existing) Object.assign(existing, values); else clinic.doctorPayments.push({ id: `doctorpay${Date.now()}`, ...values }); saveClinics(); render(); closeModal('doctorPaymentModal'); event.target.reset(); const action = existing ? 'updated' : 'saved'; editDoctorPaymentId = ''; showToast(`Doctor payment ${action}`); });
