const NAV_GROUPS_KEY = 'careledger-collapsed-groups';
function loadCollapsedGroups() { try { return JSON.parse(localStorage.getItem(NAV_GROUPS_KEY)) || []; } catch { return []; } }
function setGroupCollapsed(groupId, collapsed) { const group = document.querySelector(`.nav-group[data-group-id="${groupId}"]`); if (!group) return; group.classList.toggle('collapsed', collapsed); group.querySelector('.nav-group-title').setAttribute('aria-expanded', String(!collapsed)); const stored = loadCollapsedGroups().filter(id => id !== groupId); if (collapsed) stored.push(groupId); try { localStorage.setItem(NAV_GROUPS_KEY, JSON.stringify(stored)); } catch {} }
loadCollapsedGroups().forEach(groupId => setGroupCollapsed(groupId, true));
document.querySelectorAll('.nav-group-title').forEach(title => title.addEventListener('click', () => setGroupCollapsed(title.dataset.group, !title.parentElement.classList.contains('collapsed'))));
document.addEventListener('click', event => { const viewButton = event.target.closest('[data-view]'); if (!viewButton) return; const navItem = document.querySelector(`.nav-sub .nav-item[data-view="${viewButton.dataset.view}"]`); const group = navItem?.closest('.nav-group'); if (group?.classList.contains('collapsed')) setGroupCollapsed(group.dataset.groupId, false); });
const syncPatientGroupCount = () => { document.querySelector('#patientGroupCount').textContent = document.querySelector('#patientCount').textContent; };
syncPatientGroupCount(); new MutationObserver(syncPatientGroupCount).observe(document.querySelector('#patientCount'), { childList: true, characterData: true, subtree: true });
document.querySelector('#todayLabel').textContent = `Clinic ledger · ${new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' })}`;
const PROFILE_KEY = 'careledger-profile';
function loadProfile() { try { return { name: 'Admin', role: 'Practice manager', registration: '', ...JSON.parse(localStorage.getItem(PROFILE_KEY)) }; } catch { return { name: 'Admin', role: 'Practice manager', registration: '' }; } }
function profileInitials(name) { const words = name.replace(/^dr\.?\s+/i, '').trim().split(/\s+/).filter(Boolean); return ((words[0]?.[0] || '') + (words.length > 1 ? words.at(-1)[0] : words[0]?.[1] || '')).toUpperCase() || 'DR'; }
function renderProfile() { const profile = loadProfile(); document.querySelector('#profileName').textContent = profile.name; document.querySelector('#profileRole').textContent = [profile.role, profile.registration].filter(Boolean).join(' · ') || 'Add your title'; document.querySelector('#profileInitials').textContent = profileInitials(profile.name); const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' }); document.querySelector('#todayLabel').textContent = `${profile.name === 'Admin' ? 'Clinic ledger' : profile.name} · ${today}`; }
document.querySelector('#openProfile').addEventListener('click', () => { const profile = loadProfile(); const form = document.querySelector('#profileForm'); form.name.value = profile.name === 'Admin' ? '' : profile.name; form.role.value = profile.role === 'Practice manager' ? '' : profile.role; form.registration.value = profile.registration; openModal('profileModal'); form.name.focus(); });
document.querySelector('#profileForm').addEventListener('submit', event => { event.preventDefault(); const data = new FormData(event.target); const profile = { name: data.get('name').trim(), role: data.get('role').trim(), registration: data.get('registration').trim() }; if (!profile.name) return showToast('Enter the doctor name.'); try { localStorage.setItem(PROFILE_KEY, JSON.stringify(profile)); } catch {} renderProfile(); closeModal('profileModal'); showToast('Profile updated'); });
renderProfile();
