// Label table cells with their column heading so rows can render as cards on phones
function labelTableCells(tbody) { const headings = [...tbody.closest('table').querySelectorAll('thead th')].map(th => th.textContent.trim()); tbody.querySelectorAll('tr').forEach(row => [...row.children].forEach((cell, index) => cell.setAttribute('data-label', headings[index] || ''))); }
document.querySelectorAll('tbody').forEach(tbody => { labelTableCells(tbody); new MutationObserver(() => labelTableCells(tbody)).observe(tbody, { childList: true }); });
// Doctor-defined statuses: filter tabs
function renderStatusTabs(records) { if (activeFilter !== 'all' && !statusById(activeFilter)) activeFilter = 'all'; const tab = (id, label, count, tone = '') => `<button class="filter-tab${activeFilter === id ? ' active' : ''}" data-filter="${id}">${tone ? `<i class="tone-dot tone-${tone}"></i>` : ''}${label} <span>${count}</span></button>`; document.querySelector('#statusFilterTabs').innerHTML = tab('all', 'All patients', records.length) + setup.statuses.map(status => tab(status.id, status.label, records.filter(patient => patientStatus(patient) === status.id).length, status.tone)).join(''); }
// Patient form: plan + status choices come from the doctor's setup
function populatePatientFormChoices(statusId = setup.statuses[0].id, planId = '') { document.querySelector('#patientStatusSelect').innerHTML = setup.statuses.map(status => `<option value="${status.id}">${status.label}</option>`).join(''); document.querySelector('#patientStatusSelect').value = statusById(statusId) ? statusId : setup.statuses[0].id; document.querySelector('#patientPlanSelect').innerHTML = `<option value="">${setup.plans.length ? 'Custom treatment' : 'No plans yet: add them in Plans & statuses'}</option>` + setup.plans.map(plan => `<option value="${plan.id}">${plan.name} · ${money(plan.cost)}</option>`).join(''); document.querySelector('#patientPlanSelect').value = setup.plans.some(plan => plan.id === planId) ? planId : ''; updatePlanHint(); }
function updatePlanHint() { const plan = setup.plans.find(entry => entry.id === document.querySelector('#patientPlanSelect').value); document.querySelector('#planHint').textContent = plan ? `${plan.name} · ${money(plan.cost)}${plan.notes ? ` · ${plan.notes}` : ''}` : 'Pick a plan to fill in the treatment and cost.'; }
document.querySelector('#patientPlanSelect').addEventListener('change', event => { const plan = setup.plans.find(entry => entry.id === event.target.value); const form = document.querySelector('#patientForm'); if (plan) { form.treatment.value = plan.name; form.total.value = plan.cost; if (plan.notes && !form.notes.value) form.notes.value = plan.notes; } updatePlanHint(); });
document.querySelector('#patientForm [name="treatment"]').addEventListener('input', () => { const select = document.querySelector('#patientPlanSelect'); const plan = setup.plans.find(entry => entry.id === select.value); if (plan && document.querySelector('#patientForm').treatment.value !== plan.name) { select.value = ''; updatePlanHint(); } });
populatePatientFormChoices();
// Setup page: plans and statuses
function renderSetup() {
  const usage = (key, id) => patients.filter(patient => (key === 'status' ? patientStatus(patient) : patient.planId) === id).length;
  document.querySelector('#planList').innerHTML = setup.plans.length ? setup.plans.map(plan => `<div class="setup-item"><div class="setup-item-main"><strong>${plan.name}</strong><small>${plan.notes || 'No notes'} · ${usage('plan', plan.id)} patient${usage('plan', plan.id) === 1 ? '' : 's'}</small></div><span class="setup-price">${money(plan.cost)}</span><button class="row-action" data-edit-plan="${plan.id}" title="Edit plan">✎</button><button class="row-action danger" data-delete-plan="${plan.id}" title="Delete plan">×</button></div>`).join('') : '<div class="empty-state">No plans yet. Add your first treatment plan above.</div>';
  document.querySelector('#statusList').innerHTML = setup.statuses.map(status => `<div class="setup-item"><span class="status-badge tone-${status.tone}">${status.label}</span><div class="setup-item-main"><small>${usage('status', status.id)} patient${usage('status', status.id) === 1 ? '' : 's'}</small></div><button class="row-action" data-edit-status="${status.id}" title="Edit status">✎</button><button class="row-action danger" data-delete-status="${status.id}" title="Delete status">×</button></div>`).join('');
}
function resetSetupForm(kind) { const form = document.querySelector(`#${kind}Form`); form.reset(); form.id.value = ''; document.querySelector(`#${kind}SubmitButton`).textContent = kind === 'plan' ? '＋ Add plan' : '＋ Add status'; document.querySelector(`#cancel${kind === 'plan' ? 'Plan' : 'Status'}Edit`).classList.add('hidden'); }
document.querySelector('#planForm').addEventListener('submit', event => { event.preventDefault(); const form = event.target; const values = { name: form.name.value.trim(), cost: Number(form.cost.value), notes: form.notes.value.trim() }; if (!values.name) return; const existing = setup.plans.find(plan => plan.id === form.id.value); if (existing) Object.assign(existing, values); else setup.plans.push({ id: `plan${Date.now()}`, ...values }); saveSetup(); resetSetupForm('plan'); renderSetup(); populatePatientFormChoices(); showToast(existing ? 'Plan updated' : `${values.name} added to plans`); });
document.querySelector('#statusForm').addEventListener('submit', event => { event.preventDefault(); const form = event.target; const label = form.label.value.trim(); const tone = form.tone.value || 'blue'; if (!label) return; if (setup.statuses.some(status => status.label.toLowerCase() === label.toLowerCase() && status.id !== form.id.value)) return showToast('That status already exists.'); const existing = statusById(form.id.value); if (existing) Object.assign(existing, { label, tone }); else setup.statuses.push({ id: `status${Date.now()}`, label, tone }); saveSetup(); resetSetupForm('status'); render(); populatePatientFormChoices(); showToast(existing ? 'Status updated' : `${label} status added`); });
document.querySelector('#cancelPlanEdit').addEventListener('click', () => resetSetupForm('plan'));
document.querySelector('#cancelStatusEdit').addEventListener('click', () => resetSetupForm('status'));
document.querySelector('#setupView').addEventListener('click', event => {
  const editPlan = event.target.closest('[data-edit-plan]'); const deletePlan = event.target.closest('[data-delete-plan]'); const editStatus = event.target.closest('[data-edit-status]'); const deleteStatus = event.target.closest('[data-delete-status]');
  if (editPlan) { const plan = setup.plans.find(entry => entry.id === editPlan.dataset.editPlan); const form = document.querySelector('#planForm'); form.id.value = plan.id; form.name.value = plan.name; form.cost.value = plan.cost; form.notes.value = plan.notes || ''; document.querySelector('#planSubmitButton').textContent = 'Update plan'; document.querySelector('#cancelPlanEdit').classList.remove('hidden'); form.name.focus(); }
  if (deletePlan) { const plan = setup.plans.find(entry => entry.id === deletePlan.dataset.deletePlan); if (!confirm(`Delete the plan "${plan.name}"? Patients already added keep their treatment and cost.`)) return; setup.plans = setup.plans.filter(entry => entry !== plan); saveSetup(); renderSetup(); populatePatientFormChoices(); showToast('Plan deleted'); }
  if (editStatus) { const status = statusById(editStatus.dataset.editStatus); const form = document.querySelector('#statusForm'); form.id.value = status.id; form.label.value = status.label; form.querySelector(`[name="tone"][value="${status.tone}"]`).checked = true; document.querySelector('#statusSubmitButton').textContent = 'Update status'; document.querySelector('#cancelStatusEdit').classList.remove('hidden'); form.label.focus(); }
  if (deleteStatus) { const status = statusById(deleteStatus.dataset.deleteStatus); const inUse = patients.filter(patient => patientStatus(patient) === status.id).length; if (setup.statuses.length === 1) return showToast('Keep at least one status.'); if (inUse) return showToast(`${inUse} patient${inUse === 1 ? ' is' : 's are'} marked ${status.label}. Change them first.`); if (!confirm(`Delete the status "${status.label}"?`)) return; setup.statuses = setup.statuses.filter(entry => entry !== status); saveSetup(); render(); populatePatientFormChoices(); showToast('Status deleted'); }
});
// Doctor payment: visit dates are fixed, show what is still due for each
function doctorDueForDate(date, excludeId = '') { const collected = clinicPatients().flatMap(patient => patient.payments).filter(payment => payment.date === date).reduce((sum, payment) => sum + Number(payment.amount), 0); const share = collected * (activeClinic().doctorSharePercent / 100); const received = (activeClinic().doctorPayments || []).filter(payment => (payment.visitDate || payment.date) === date && payment.id !== excludeId).reduce((sum, payment) => sum + Number(payment.amount), 0); return { share, received, due: Math.max(0, share - received) }; }
function populateDoctorVisitSelect(selected = '', excludeId = '') { const dates = [...new Set(clinicPatients().flatMap(patient => patient.payments.map(payment => payment.date)))].sort((a, b) => b.localeCompare(a)); if (selected && !dates.includes(selected)) dates.unshift(selected); const select = document.querySelector('#doctorVisitSelect'); select.dataset.excludeId = excludeId; select.innerHTML = dates.length ? dates.map(date => { const { due } = doctorDueForDate(date, excludeId); return `<option value="${date}">${bsLabel(date)} · ${due > 0 ? `due ${money(due)}` : 'settled'}</option>`; }).join('') : '<option value="">No patient visits yet</option>'; select.value = selected && dates.includes(selected) ? selected : dates[0] || ''; }
function updateDoctorVisitPreview(fillAmount) { const select = document.querySelector('#doctorVisitSelect'); const preview = document.querySelector('#doctorVisitBsPreview'); if (!select.value) { preview.textContent = 'Record a patient visit first.'; return; } const { share, received, due } = doctorDueForDate(select.value, select.dataset.excludeId); preview.innerHTML = `Doctor share ${money(share)} · received ${money(received)} · <strong class="${due > 0 ? 'due-text' : 'settled-text'}">${due > 0 ? `due ${money(due)}` : 'settled'}</strong>`; if (fillAmount) document.querySelector('#doctorPaymentForm [name="amount"]').value = due > 0 ? Math.round(due * 100) / 100 : ''; }
